import { createRouter, Router, params, back } from "march/router"
import { Card, Button, ListRow, Badge } from "march/ui"
import { book } from "march/icons"

// kitap kulübü: raf ve kitap sayfası iki rota; kitabın sayfası adresteki :id'yi okur, Geri bir önceki sayfaya döner
const BOOKS = [
  { id: "1", title: "Kürk Mantolu Madonna", author: "Sabahattin Ali", pages: 160, mood: "Hüzünlü" },
  { id: "2", title: "Tutunamayanlar", author: "Oğuz Atay", pages: 724, mood: "Derin" },
  { id: "3", title: "Saatleri Ayarlama Enstitüsü", author: "Ahmet Hamdi Tanpınar", pages: 382, mood: "Esprili" },
]

// raf: her kitap kendi sayfasına giden bir satır
function Shelf() {
  return <Card title="Bu ayın rafı">
    {BOOKS.map((b) => <ListRow href={`/kitap/${b.id}`} lead={book} title={b.title} sub={b.author} trail={<Badge tone="neutral">{b.mood}</Badge>} />)}
  </Card>
}

// kitabın sayfası: hangi kitap olduğunu adres söyler (/kitap/2)
function Book() {
  const book = BOOKS.find((b) => b.id === params().id)
  return <Card title={book?.title ?? "Böyle bir kitap yok"} subtitle={book?.author}>
    <p sx={{ color: "muted" }}>{book ? `${book.pages} sayfa · ${book.mood}` : "Raf değişmiş olabilir."}</p>
    <Button variant="secondary" on:click={() => back()}>← Rafa dön</Button>
  </Card>
}

export function BookClub() {
  createRouter({ routes: { "/": { component: Shelf }, "/kitap/:id": { component: Book } } })
  return <div sx={{ w: "sm" }}>
    <Router notFound={<p>Bu raf boş.</p>} />
  </div>
}

import { createRouter, Router, Outlet, Link } from "march/router"
import { Card, Button, ListRow, TextInput, Badge } from "march/ui"

// ekip gelen kutusu: çerçeve (yanıt taslağı) bir kez kurulur, sekmeler altında değişir; bir mesaj yan panelde açılır
// (adlı outlet: adres ?~aside=/mesaj/2 olur), liste yerinde kalır
const MAILS = [
  { id: "1", from: "Ece", subject: "Cumartesi koşusu 08:30'da", body: "Moda iskelesinde buluşuyoruz, sonra kahvaltı.", archived: false },
  { id: "2", from: "Mert", subject: "Sunum dosyası", body: "Son hâli ekte; slayt 7'ye bir bakar mısın?", archived: false },
  { id: "3", from: "Kitap Kulübü", subject: "Ayın kitabı", body: "İlk üç bölümü okuyup gelin.", archived: true },
]

// bir mesaj: yan panelde açılan sayfa (parametresini props.params ile alır)
function Mail(props: { params?: Record<string, string> }) {
  const mail = MAILS.find((m) => m.id === props.params?.id)
  return <Card title={mail?.subject ?? "Mesaj bulunamadı"} subtitle={mail?.from}><p>{mail?.body}</p></Card>
}

// bir kutu: arşivli ya da değil
const box = (archived: boolean) => () => <div sx={{ flex: "col", gap: 1 }}>
  {MAILS.filter((m) => m.archived === archived).map((m) => <ListRow title={m.subject} sub={m.from}
    actions={<Link href={`/mesaj/${m.id}`} outlet="aside">Yanda aç</Link>} />)}
</div>

// çerçeve: sekmeler ve taslak burada; sekme değişince yalnız <Outlet /> değişir, yazdığın taslak kalır
function Shell() {
  let $draft = ""
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button href="/" exact size="sm">Gelen</Button>
      <Button href="/arsiv" size="sm">Arşiv</Button>
      <Badge tone="info">{$draft ? "Taslak var" : "Taslak yok"}</Badge>
    </div>
    <TextInput bind:value={$draft} placeholder="Yanıt taslağı: sekme değişince kalır" aria-label="Yanıt taslağı" />
    <div sx={{ flex: "row", gap: 3 }}>
      <div sx={{ flex: "grow" }}><Outlet /></div>
      <div sx={{ flex: "grow" }}><Outlet name="aside" empty={<p sx={{ color: "muted" }}>Bir mesajı yanda açın.</p>} /></div>
    </div>
  </div>
}
const shell = async () => ({ default: Shell })

export function TeamInbox() {
  createRouter({
    routes: { "/": { component: box(false), layouts: [shell] }, "/arsiv": { component: box(true), layouts: [shell] } },
    outlets: { aside: { "/mesaj/:id": { component: Mail } } },
  })
  return <div sx={{ w: "lg" }}><Router /></div>
}

import { createRouter, Router, Outlet, Link, back, path, query, setQuery } from "march/router"
import { Button, Card, ListRow, TextInput, Toggle, Dialog } from "march/ui"

// Yönlendiricinin bütün özellikleri bir arada: routes (parametreli yol, bileşen, layouts), redirects, guard, outlets
// (adlı outlet), Router (notFound), Outlet (sıradaki düzey, adlı, modal), Link (outlet, modal), Button href (exact),
// back, path, query ve setQuery. Önizlemede yönlendirici kendi adresini tutar (memoryHistory): sayfanın adresi değişmez
const CITIES = [
  { id: "izmir", name: "İzmir", note: "Kordon'da gün batımı" },
  { id: "mardin", name: "Mardin", note: "Taş evler, dar sokaklar" },
  { id: "rize", name: "Rize", note: "Yeşilin her tonu" },
]

// bir şehir: sayfa, yan panel ya da pencere olarak açılır; parametresi props.params'ta
function City(props: { params?: Record<string, string> }) {
  const city = CITIES.find((c) => c.id === props.params?.id)
  return <Card title={city?.name ?? "Bilinmeyen şehir"} class="lab-city"><p>{city?.note}</p></Card>
}

// şehirler: ?sirala=za adresin parçası (setQuery), her şehir üç yoldan açılır
function Cities() {
  const za = () => query().sirala === "za"
  return <div sx={{ flex: "col", gap: 1 }}>
    <Button size="sm" variant="ghost" class="lab-sort" on:click={() => setQuery({ sirala: za() ? null : "za" })}>{za() ? "A → Z sırala" : "Z → A sırala"}</Button>
    {() => [...CITIES].sort((a, b) => (za() ? -1 : 1) * a.name.localeCompare(b.name, "tr")).map((c) => <ListRow title={c.name} sub={c.note}
      actions={<div sx={{ flex: "row", gap: 2 }}>
        <Link href={`/sehir/${c.id}`}>Aç</Link>
        <Link href={`/sehir/${c.id}`} outlet="aside">Yanda</Link>
        <Link href={`/sehir/${c.id}`} modal>Pencerede</Link>
      </div>} />)}
  </div>
}
const About = () => <p class="lab-about">Bu çerçeve bir kez kurulur; sekmeler altında değişir.</p>
const Admin = () => <p class="lab-admin">Yönetim paneli: yalnız yöneticiler.</p>

// yerleşim: gezinme, adres, not ve üç outlet (sıradaki düzey, yan panel, pencere)
function Frame() {
  let $note = ""
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "center", "wrap"], gap: 2 }}>
      <Button href="/" exact size="sm">Şehirler</Button>
      <Button href="/hakkinda" size="sm">Hakkında</Button>
      <Button href="/yonetim" size="sm">Yönetim</Button>
      <Button href="/eski" size="sm" variant="ghost">Eski adres</Button>
      <Button href="/kayip" size="sm" variant="ghost">Kayıp sayfa</Button>
      <Button size="sm" variant="ghost" on:click={() => back()}>← Geri</Button>
    </div>
    <code class="lab-path">{path() + (query().sirala ? `?sirala=${query().sirala}` : "")}</code>
    <TextInput bind:value={$note} placeholder="Not: sayfa değişince kalır" aria-label="Not" class="lab-note" />
    <div sx={{ flex: "row", gap: 3 }}>
      <div sx={{ flex: "grow" }}><Outlet /></div>
      <div sx={{ flex: "grow" }}><Outlet name="aside" empty={<p sx={{ color: "muted" }} class="lab-aside-empty">Yan panel boş</p>} /></div>
    </div>
    <Outlet name="modal">{(page: () => unknown, close: () => void) => <Dialog open onClose={close} title="Şehir" closeLabel="Pencereyi kapat">{page()}</Dialog>}</Outlet>
  </div>
}
const frame = async () => ({ default: Frame })

export function RoutingLab() {
  let $admin = false
  createRouter({
    routes: {
      "/": { component: Cities, layouts: [frame] },
      "/hakkinda": { component: About, layouts: [frame] },
      "/yonetim": { component: Admin, layouts: [frame] },
      "/sehir/:id": { component: City, layouts: [frame] },
    },
    // eski bir adres yenisine gider; yönetim yalnız yöneticiye açılır (değilse şehirlere döner)
    redirects: { "/eski": "/hakkinda" },
    guard: (to) => (to.path === "/yonetim" && !$admin ? "/" : true),
    outlets: { aside: { "/sehir/:id": { component: City } } },
  })
  return <div sx={{ flex: "col", gap: 3 }}>
    <Toggle label="Yönetici girişi (guard)" bind:value={$admin} />
    <Router notFound={<p class="lab-404">Böyle bir sayfa yok.</p>} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { RoutingLab } from "./RoutingLab.tsx"

// RoutingLab'in testleri: kaydedince Testler sekmesinde çalışır
test("şehre gidince adres ve sayfa değişir, not yerinde kalır", async () => {
  const s = renderTest(() => <RoutingLab />)
  await s.flush(3)
  await s.type(".lab-note", "unutma")
  await s.click("Aç")
  await s.flush(3)
  expect(s.get(".lab-path")?.textContent).toContain("/sehir/")
  expect(s.get(".lab-city")).not.toBe(null)
  expect((s.get(".lab-note") as HTMLInputElement | null)?.value).toBe("unutma")
})

test("yanda açınca liste kalır, yan panel dolar", async () => {
  const s = renderTest(() => <RoutingLab />)
  await s.flush(3)
  await s.click("Yanda")
  await s.flush(3)
  expect(s.get(".lab-aside-empty")).toBe(null)
  expect(s.sees("Z → A sırala")).toBe(true)
})

test("guard: yönetici değilken yönetim şehirlere döner", async () => {
  const s = renderTest(() => <RoutingLab />)
  await s.flush(3)
  await s.click("Yönetim")
  await s.flush(3)
  expect(s.get(".lab-admin")).toBe(null)
  await s.click("Yönetici girişi (guard)")
  await s.click("Yönetim")
  await s.flush(3)
  expect(s.get(".lab-admin")).not.toBe(null)
})

test("eski adres yönlendirilir, bilinmeyen adres notFound gösterir", async () => {
  const s = renderTest(() => <RoutingLab />)
  await s.flush(3)
  await s.click("Eski adres")
  await s.flush(3)
  expect(s.get(".lab-about")).not.toBe(null)
  await s.click("Kayıp sayfa")
  await s.flush(3)
  expect(s.get(".lab-404")).not.toBe(null)
})
